package com.iotiq.partnererp.modules.payments.dto;

import com.iotiq.partnererp.modules.payments.entity.PaymentMethod;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.UUID;

/**
 * Record a receipt against an issued invoice (Payments write). Amounts include GST; the ex-GST part is computed by the
 * server.
 *
 * @param idempotencyKey   generated by the client once per form; resubmitting it returns the entry already recorded
 * @param confirmDuplicate true after the user has seen a possible-duplicate warning and confirmed the receipt
 */
public record PaymentRequest(UUID invoiceId, LocalDate paymentDate, BigDecimal amount, PaymentMethod method,
                             String reference, String notes, UUID idempotencyKey, Boolean confirmDuplicate) {
}
